up=[r['frame']for r in b if r['game_held']&0x100000];left=[r['frame']for r in b if r['game_held']&0x400000];assert up==list(range(360,420)) and left==list(range(420,450));assert not b[-1]['game_held'];reference=(Path(control['directory'])/'RAM-after.bin').read_bytes();reference_Z=int.from_bytes(reference[0x49c56:0x49c5a],'big');input_Z=b[-1]['player_state']['0x49c56'];assert reference_Z==40096 and input_Z==40073;busy_zero=sum(r['draw_busy']==0 for r in b);assert busy_zero>0
out=ROOT/'verification/BIWN-native-input-pair'/datetime.now(timezone.utc).strftime('%Y%m%dT%H%M%S.%fZ');out.mkdir(parents=True)
report=dict(status='paired_native_emulated_input_response_checked',directory=str(out),control=control['directory'],input=test['directory'],same_source_checkpoint_and_core=True,matched_pre_input_frames=359,pre_input_comparison='SampledCPU/GPU/DSP PC/context/clock/CD state and completeRAM SHA256; not all hidden serialized core state.',first_RAM_divergence_frame=360,Up_held_frames=[360,419],Left_held_frames=[420,449],game_Up_mask='0x100000',game_Left_mask='0x400000',final_buttons_released=True,reference_Z=reference_Z,input_Z=input_Z,busy_zero_observations=busy_zero,CPU_sampled_in_multiple_tasks=True,frontend_image=str(Path(test['directory'])/'frame-600.png'),original_CPU_GPU_DSP_video_CD_schedule=True,C_execution=False,physical_controller=False,ordinary_fresh_boot=False,whole_game_complete=False,limits=['Input callback supplies standard emulated button events; source memory/PC/counters/poses are not directly rewritten after restore. No physical-controller or complete-game validation.','Earlier captured firmware/ROM/CD/SSI/GPU-stack inputs remain. Native timing/model/fastblitter are emulator assumptions; physical hardware accuracy is unverified.','RepeatedCPU17E62 samples are active render-wait observations;144zero-busy frames and changed tasks refute treating those sampledPCs alone as a deadlock.'])
